        dy = 0 if ty == y else (1 if ty > y else -1)
        return [dx, dy]

    # Build frontier targets: unclaimed cells adjacent to opponent territory.
    frontier = []
    if oppT and unclaimed:
        for ux, uy in unclaimed:
            ok = False
            for ddx, ddy in dirs:
                if ddx == 0 and ddy == 0:
                    continue
                nx, ny = ux + ddx, uy + ddy
                if (nx, ny) in oppT:
                    ok = True
                    break
            if ok:
                frontier.append((ux, uy))

    opp_focus = None
    if oppT:
        # Use a deterministic proxy: closest opponent territory cell to us.
        ox, oy = min(oppT, key=lambda p: (man(x, y, p[0], p[1]), p[1], p[0]))
        opp_focus = (ox, oy)

    def cell_score(nx, ny):
        s = 0.0
