            s += 18.0  # direct flip pressure
        if (nx, ny) in selfT:
            s += 3.0  # consolidation
        if (nx, ny) in unclaimed:
            s += 2.5  # expand
        # Risk/pressure: count adjacent opponent territory
        adj_opp = 0
        for ddx, ddy in dirs:
