                continue
            ax, ay = nx + ddx, ny + ddy
            if (ax, ay) in oppT:
                adj_opp += 1
        s += 1.0 * adj_opp  # approaching their border is good for center-claim archetype
        # Encourage frontier targeting; otherwise approach closest opponent territory
